sdl:
directive @cost(weight: String!) on ARGUMENT_DEFINITION | ENUM | FIELD_DEFINITION | INPUT_FIELD_DEFINITION | OBJECT | SCALAR
directive @listSize(
  assumedSize: Int
  slicingArguments: [String!]
  sizedFields: [String!]
  requireOneSlicingArgument: Boolean = true
) on FIELD_DEFINITION
input Filter { approximate: Boolean @cost(weight: "-12.0") }
type Query { products(filter: Filter @cost(weight: "15.0")): String @cost(weight: "5.0") }
